const plantingPhotos={"tomato": {"url": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Tomato_je.jpg/960px-Tomato_je.jpg", "source": "https://commons.wikimedia.org/wiki/File:Tomato_je.jpg", "author": "Softeis", "license": "CC BY-SA 3.0", "licenseUrl": "http://creativecommons.org/licenses/by-sa/3.0/"}, "cucumber": {"url": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/ARS_cucumber.jpg/960px-ARS_cucumber.jpg", "source": "https://commons.wikimedia.org/wiki/File:ARS_cucumber.jpg", "author": "Stephen Ausmus, USDA ARS", "license": "Public domain", "licenseUrl": ""}, "carrot": {"url": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Vegetable-Carrot-Bundle-wStalks.jpg/960px-Vegetable-Carrot-Bundle-wStalks.jpg", "source": "https://commons.wikimedia.org/wiki/File:Vegetable-Carrot-Bundle-wStalks.jpg", "author": "Evan-Amos", "license": "Public domain", "licenseUrl": ""}, "radish": {"url": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Radish_3371103037_4ab07db0bf_o.jpg/960px-Radish_3371103037_4ab07db0bf_o.jpg", "source": "https://commons.wikimedia.org/wiki/File:Radish_3371103037_4ab07db0bf_o.jpg", "author": "Self, en:User:Jengod", "license": "Public domain", "licenseUrl": ""}, "dill": {"url": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Liat_Portal_for_Foodie_Disorder_-_Fresh_Dill.jpg/960px-Liat_Portal_for_Foodie_Disorder_-_Fresh_Dill.jpg", "source": "https://commons.wikimedia.org/wiki/File:Liat_Portal_for_Foodie_Disorder_-_Fresh_Dill.jpg", "author": "HaJunkiyada", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0"}, "parsley": {"url": "https://upload.wikimedia.org/wikipedia/commons/b/bf/Parsley100.jpg", "source": "https://commons.wikimedia.org/wiki/File:Parsley100.jpg", "author": "Tharish", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0"}};
let plantingSelection=null,plantingBusy=false;
gamePlant=async function(plot){closeFieldMenu();try{const userId=account?.id;const data=await api('planting-offers',{plot});if(account?.id!==userId)return;plantingSelection={plot,offers:data.offers,keys:Object.fromEntries(data.offers.map(x=>[x.id,crypto.randomUUID()]))};modalForm('Что вырастим на грядке?',`<p>Грядка №${plot} · вся площадь. Выберите овощ — мы подготовим необходимое количество семян и отправим садовнику задачу.</p><p class="planting-payment-note">Кнопка «Посадить» сразу списывает указанную сумму с демобаланса. Семена, посадка${data.offers[0]?.quote.prepare?' и подготовка почвы':''} включены.</p><div class="planting-photo-grid">${data.offers.map(c=>{const photo=plantingPhotos[c.id];return `<article class="planting-photo-card"><img src="${esc(photo.url)}" alt="${esc(c.name)} — пример будущего урожая" loading="eager" referrerpolicy="no-referrer"><div><h3>${esc(c.name)}</h3><p>Вся грядка · работа ~${c.quote.minutes} мин.</p><button type="button" class="btn planting-buy" data-crop="${c.id}" onclick="plantingBuy('${c.id}',this)">Посадить · ${money(c.quote.price)}</button></div></article>`}).join('')}</div><p class="note">Фото показывает культуру, а не гарантированный результат или конкретный сорт. Время в задаче учитывает свободную смену 09:00–19:00. Таймер относится к посадке, не к созреванию.</p><details><summary>Авторы фотографий</summary>${data.offers.map(c=>{const p=plantingPhotos[c.id];return `<p>${esc(c.name)}: <a href="${esc(p.source)}" target="_blank" rel="noopener">${esc(p.author)}</a> · ${p.licenseUrl?`<a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener">${esc(p.license)}</a>`:esc(p.license)}</p>`}).join('')}</details>`,()=>{})}catch(e){toast(e.message)}};
async function plantingBuy(crop,button){if(plantingBusy||!plantingSelection)return;const selection=plantingSelection,offer=selection.offers.find(x=>x.id===crop);if(!offer)return;plantingBusy=true;document.querySelectorAll('.planting-buy').forEach(x=>x.disabled=true);button.textContent='Создаём задачу…';try{const data=await api('planting-buy',{plot:selection.plot,crop,price:offer.quote.price,key:selection.keys[crop]});modal.close();walletData=null;await loadOperations();location.hash='orders';render();toast('Посадка оплачена демобалансом. Задача назначена садовнику.')}catch(e){toast(e.message);button.textContent='Посадить · '+money(offer.quote.price);document.querySelectorAll('.planting-buy').forEach(x=>x.disabled=false)}finally{plantingBusy=false}}
const beforePlantingOrderCard=orderCard;
orderCard=function(o){const html=beforePlantingOrderCard(o);if(o.service_code!=='plant_package')return html;const active=!['done','cancelled'].includes(o.status),photo=plantingPhotos[o.planting_crop];return html.replace('<article class="panel">',`<article class="panel planting-task">${photo?`<img class="planting-task-photo" src="${esc(photo.url)}" alt="${esc(o.title)}" referrerpolicy="no-referrer">`:''}${active?`<div class="planting-timer"><span>⏳ До планового завершения посадки</span><strong data-planting-deadline="${esc(o.finish_by)}">Считаем время…</strong><small>${o.status==='working'?'Садовник выполняет работу':'Задача в очереди садовника'}. По окончании таймера потребуется подтверждение выполнения.</small></div>`:''}`)};
function updatePlantingTimers(){document.querySelectorAll('[data-planting-deadline]').forEach(el=>{const seconds=Math.ceil((Date.parse(el.dataset.plantingDeadline)-Date.now())/1000);if(!Number.isFinite(seconds)){el.textContent='Уточняем срок';return}el.textContent=seconds<=0?'Срок наступил · ждём отчёт':`${Math.floor(seconds/3600)}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`})}
setInterval(()=>{if(!document.hidden)updatePlantingTimers()},1000);farmViews.add(updatePlantingTimers);
const beforePackageRoomService=roomService;
roomService=function(p,code,icon,title,description){if(code==='plant')return roomTile('🌱','Посадить овощи','Фотографии культур, семена и работа одним заказом',`gamePlant(${p.id})`,'Выбрать культуру и увидеть полную цену');return beforePackageRoomService(p,code,icon,title,description)};
